const input = $input.first().json;
const body = input.body || input;

const errors = [];

if (!body.discord_user_id) {
  errors.push('Missing required parameter: discord_user_id');
}

if (!body.label) {
  errors.push('Missing required parameter: label');
}

// Bot token from request or environment
const botToken = body.discord_bot_token || process.env.DISCORD_BOT_TOKEN;
if (!botToken) {
  errors.push('Missing discord_bot_token (pass in request or set DISCORD_BOT_TOKEN env var)');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

return [{
  json: {
    valid: true,
    discord_user_id: body.discord_user_id,
    discord_bot_token: botToken,
    timer_id: body.timer_id,
    recipe_id: body.recipe_id,
    recipe_title: body.recipe_title || '',
    label: body.label,
    duration_minutes: body.duration_minutes || 0,
    created_at: body.created_at,
    expired_at: new Date().toISOString()
  }
}];

