const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const dmChannel = $('Create DM Channel').first().json;

try {
  // Check for Discord API errors
  if (input.code || input.message) {
    return [{
      json: {
        success: false,
        error: {
          code: input.code || 500,
          message: input.message || 'Discord DM failed',
          status: 'DISCORD_ERROR'
        },
        meta: { provider: 'discord' }
      }
    }];
  }

  if (dmChannel.code || dmChannel.message) {
    return [{
      json: {
        success: false,
        error: {
          code: dmChannel.code || 500,
          message: 'Failed to create DM channel: ' + (dmChannel.message || 'Unknown error'),
          status: 'DISCORD_DM_ERROR'
        },
        meta: { provider: 'discord' }
      }
    }];
  }

  return [{
    json: {
      success: true,
      data: {
        notification_sent: true,
        delivery_method: 'dm',
        timer_id: prevData.timer_id,
        discord_user_id: prevData.discord_user_id,
        dm_channel_id: dmChannel.id,
        message_id: input.id,
        label: prevData.label,
        sent_at: new Date().toISOString()
      },
      meta: {
        provider: 'discord'
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to process notification: ' + e.message,
        status: 'PROCESS_ERROR'
      },
      meta: { provider: 'discord' }
    }
  }];
}

